css:
/* 大円で抜き、下辺だけ直線で断つ */
.photo{clip-path:circle(52% at 50% 42%)}
.photo img{clip-path:inset(0 0 22% 0)}
/* 細帯で巨大円を窓抜き */
.rail{position:absolute;inset:0 auto 0 0;width:10%;overflow:hidden;background:#e4e9f0}
.rail::after{content:"";position:absolute;left:-140px;top:25px;width:280px;aspect-ratio:1;
             border-radius:50%;background:#12304c}
/* 矩形スクリムの代わりに画面幅級の楕円 */
section{position:relative;overflow:hidden}
section::before{content:'';position:absolute;left:-4%;top:-12%;width:108%;height:125%;
  border-radius:50%;background:rgba(255,255,255,.85);backdrop-filter:blur(4px);z-index:1}
section .inner{position:relative;z-index:2}
/* 装飾は面の縁で断つ */
.panel{position:relative;overflow:hidden}
.panel::after{content:"";position:absolute;left:24px;bottom:-26px;width:60px;height:60px;
  background:url(sparkle.svg) center/contain no-repeat;opacity:.5}
